  int get observationCount => OBSERVATION_COUNT;
  ///  Predicted objects (prediction blocks) read.
  int get PREDICTION_COUNT => const fb.Uint32Reader().vTableGet(_bc, _bcOffset, 14, 0);
  int get predictionCount => PREDICTION_COUNT;
