  int get scanCount => SCAN_COUNT;
  ///  Observations associated.
  int get ASSOCIATED_COUNT => const fb.Uint32Reader().vTableGet(_bc, _bcOffset, 18, 0);
  int get associatedCount => ASSOCIATED_COUNT;
  ///  Observations left uncorrelated.
  int get UNCORRELATED_COUNT => const fb.Uint32Reader().vTableGet(_bc, _bcOffset, 20, 0);
